INSERT OR IGNORE INTO academy_knowledge (id, kind, category, title_pl, title_en, content_pl, content_en, tags, source_ref) VALUES
('topic:TOPIC311-011','topic','','Diagnostyka pamięci VRAM i testy artefaktów GPU','GPU VRAM diagnostics and artifact testing','description: Oddziel pamięć VRAM, rdzeń GPU, sterownik, temperaturę hotspot, zasilanie, kabel i monitor. Artefakt widoczny na zrzucie ekranu wskazuje inny tor niż artefakt wyłącznie na fizycznym wyświetlaczu. symptoms: Pojawiają się kolorowe bloki, błędy tekstur, migotanie, sterownik resetuje się albo test 3D zgłasza błędy. diagnosis: Zacznij od ustawień fabrycznych i stabilnego sterownika. Zapisz temperaturę, obciążenie i test. Nie stosuj długiego stresu przy błędach lub przegrzewaniu. repair: Przerwij test przy zapachu, dymie, niestabilnym zasilaniu lub temperaturze poza limitem producenta. warning: Zapisz model GPU, VBIOS i wersję sterownika.','descriptionEn: Separate VRAM, GPU core, hotspot temperature, driver, power, cable and monitor. An artifact captured in a screenshot indicates a different path from one visible only on the physical display. symptomsEn: Coloured blocks, texture corruption, flicker, driver resets or errors in 3D tests appear. diagnosisEn: Start with factory settings and a stable driver. Record temperature, load and test. Do not run prolonged stress tests when errors or overheating occur. repairEn: Stop testing for smell, smoke, unstable power or temperatures outside vendor limits. warningEn: Record GPU model, VBIOS and driver version.','',''),
('topic:TOPIC311-012','topic','','Diagnostyka monitora: EDID, HDR i profil kolorów','Monitor diagnostics: EDID, HDR and colour profile','description: Sprawdź EDID, kabel, wejście, przepustowość, tryb GPU, ustawienia OSD, HDR i profil ICC. EDID może być ograniczony przez adapter, KVM lub stację. symptoms: Nieprawidłowa rozdzielczość, odświeżanie, HDR, kolory albo monitor jest wykrywany jako Generic PnP. diagnosis: Porównaj bezpośrednie połączenie i innym przewodem o wymaganej przepustowości. Zresetuj profil dopiero po zapisaniu ustawień klienta. repair: Nie wymuszaj trybów poza specyfikacją panelu. Nie używaj niezweryfikowanych EDID override w środowisku klienta. warning: Zapisz model monitora i wersję firmware.','descriptionEn: Check EDID, cable, input, bandwidth, GPU mode, OSD settings, HDR and ICC profile. EDID can be limited by an adapter, KVM or dock. symptomsEn: Incorrect resolution, refresh rate, HDR or colours, or the monitor appears as Generic PnP. diagnosisEn: Compare a direct connection and another cable with the required bandwidth. Reset profiles only after recording customer settings. repairEn: Do not force modes outside panel specifications. Avoid unverified EDID overrides on customer systems. warningEn: Record monitor model and firmware version.','',''),
('topic:TOPIC311-013','topic','','Diagnostyka kontrolera USB i zasilania portów','USB host controller and port power diagnostics','description: Rozróżnij awarię pojedynczego gniazda, grupy portów, kontrolera, zasilania VBUS, kabla, urządzenia i sterownika chipsetu. symptoms: Kilka portów USB nie działa, pojawiają się rozłączenia lub urządzenia mają błąd enumeracji. diagnosis: Porównaj urządzenie na innym komputerze i porty z różnych kontrolerów. Sprawdź dzienniki USB i zasilanie według specyfikacji modelu. repair: Nie zwieraj VBUS do GND. Przed naprawą gniazda odłącz baterię i zasilanie oraz sprawdź ryzyko uszkodzenia linii danych. warning: Zapisz urządzenie, kabel i port, na którym występuje problem.','descriptionEn: Distinguish a single connector, port group, controller, VBUS power, cable, device and chipset-driver fault. symptomsEn: Several USB ports fail, disconnect intermittently or show enumeration errors. diagnosisEn: Test the device on another computer and ports on different controllers. Review USB logs and power against the model specification. repairEn: Never short VBUS to ground. Disconnect battery and power before connector repair and assess the risk to data lines. warningEn: Record the device, cable and port showing the issue.','',''),
('topic:TOPIC311-014','topic','','Analiza dzienników Linux: journalctl, dmesg i systemd','Linux logs: journalctl, dmesg and systemd analysis','description: Zbierz dziennik rozruchu, komunikaty jądra, status systemd, wersję kernela i identyfikatory urządzeń. Powiąż wpisy z czasem awarii. symptoms: Linux nie wykrywa urządzenia, usługa nie startuje, system zawiesza się lub występują błędy I/O. diagnosis: Używaj trybu odczytu i zachowaj logi przed aktualizacją. Dla dysków w złym stanie nie wykonuj benchmarków; najpierw kopia sektorowa. repair: Nie wpisuj poleceń kasujących lub zmieniających partycje bez zweryfikowania urządzenia i kopii. warning: Zapisz dystrybucję, kernel i czas awarii.','descriptionEn: Collect boot journal, kernel messages, systemd status, kernel version and device identifiers. Correlate entries with the failure time. symptomsEn: Linux fails to detect a device, a service does not start, the system hangs or I/O errors occur. diagnosisEn: Use read-only inspection and preserve logs before updates. Do not benchmark a failing disk; image it first. repairEn: Do not run destructive or partition-changing commands without verifying the target and backup. warningEn: Record distribution, kernel and failure time.','',''),
('topic:TOPIC311-015','topic','','Diagnostyka karty sieciowej Wi-Fi 6/6E/7 i pasm','Wi-Fi 6/6E/7 adapter and band diagnostics','description: Sprawdź region, kanał, szerokość pasma, sterownik, anteny, MIMO, DFS, WPA mode, możliwości routera i zakłócenia radiowe. symptoms: Połączenie jest wolne, niestabilne, zrywa przy roamingu lub komputer nie widzi określonego pasma. diagnosis: Porównaj z urządzeniem referencyjnym w tym samym miejscu i sprawdź lokalne wymagania regulacyjne. Nie wymuszaj niedozwolonych kanałów. repair: Nie zmieniaj ustawień regionu radiowego, aby odblokować nielegalne pasma lub moc nadawania. warning: Zapisz model adaptera, routera i region.','descriptionEn: Check region, channel, channel width, driver, antennas, MIMO, DFS, WPA mode, router capabilities and RF interference. symptomsEn: The connection is slow, unstable, drops during roaming or the computer cannot see a specific band. diagnosisEn: Compare with a reference device in the same location and check local regulatory requirements. Do not force prohibited channels. repairEn: Do not alter radio region settings to unlock illegal bands or transmit power. warningEn: Record adapter, router model and region.','',''),
('topic:TOPIC311-016','topic','','Diagnostyka dysku SSD: TRIM, garbage collection i zużycie','SSD diagnostics: TRIM, garbage collection and endurance','description: Sprawdź temperaturę, procent zużycia, media errors, unsafe shutdowns, firmware, TRIM i rodzaj obciążenia. Wynik benchmarku chwilowego nie opisuje całej kondycji dysku. symptoms: Spadek prędkości zapisu, opóźnienia, błędy SMART lub nietypowe zużycie nośnika. diagnosis: Najpierw zabezpiecz dane i odczytaj SMART/NVMe log. Nie uruchamiaj testów zapisu na nośniku z objawami awarii. repair: Jeśli nośnik znika, klika lub raportuje błędy mediów, ogranicz zasilanie i wykonaj kopię/obraz odpowiednią metodą. warning: Zapisz model, firmware, temperaturę i host writes.','descriptionEn: Check temperature, percentage used, media errors, unsafe shutdowns, firmware, TRIM and workload type. A short benchmark does not describe overall drive health. symptomsEn: Write performance drops, latency rises, SMART errors appear or wear is unusual. diagnosisEn: Back up data first and read SMART/NVMe logs. Do not run write tests on a drive showing failure symptoms. repairEn: If the drive disappears, clicks or reports media errors, minimize power cycles and create an appropriate backup/image. warningEn: Record model, firmware, temperature and host writes.','',''),
('topic:TOPIC311-017','topic','','Diagnostyka błędów NTFS, ReFS i dziennika systemu plików','NTFS, ReFS and filesystem journal diagnostics','description: Oddziel uszkodzenie systemu plików od awarii nośnika, kabla, kontrolera i pamięci RAM. Sprawdź Event Viewer, SMART i historię nieprawidłowych wyłączeń. symptoms: Wolumin przechodzi w tryb tylko do odczytu, pojawiają się błędy I/O, uszkodzone wpisy lub komunikaty naprawy. diagnosis: Zabezpiecz dane przed CHKDSK/repair. Dobierz tryb sprawdzania do sytuacji i nie uruchamiaj naprawy na nośniku fizycznie niestabilnym. repair: Nie uruchamiaj naprawy z parametrem modyfikującym dane, zanim nie powstanie kopia. Przy podejrzeniu awarii fizycznej priorytetem jest obraz nośnika. warning: Zapisz objawy i kod błędu.','descriptionEn: Separate filesystem corruption from drive, cable, controller and RAM failure. Check Event Viewer, SMART and unexpected-shutdown history. symptomsEn: A volume becomes read-only, I/O errors occur, entries are corrupted or repair prompts appear. diagnosisEn: Back up data before CHKDSK or repair. Choose the scan mode for the situation and do not repair a physically unstable drive. repairEn: Do not run data-modifying repair options before creating a backup. If physical failure is suspected, imaging takes priority. warningEn: Record symptoms and error code.','',''),
('topic:TOPIC311-018','topic','','Kontrola kompatybilności pamięci RAM i listy QVL','RAM compatibility and QVL verification','description: Sprawdź typ DDR, obsługę CPU, liczbę rang, gęstość układów, obsadzenie slotów, QVL i wersję BIOS. QVL nie gwarantuje każdej kombinacji i rewizji. symptoms: System nie startuje z nowymi modułami, nie osiąga profilu albo wykrywa mniejszą pojemność. diagnosis: Testuj moduły pojedynczo w zalecanych slotach i na ustawieniach JEDEC. Profil XMP/EXPO włączaj dopiero po teście bazowym. repair: Nie mieszaj napięć i timingów z niezgodnych profili. Nie uznawaj samego startu za dowód stabilności. warning: Zapisz modele, numery części i rewizje modułów.','descriptionEn: Check DDR type, CPU support, rank count, chip density, slot population, QVL and BIOS version. QVL does not guarantee every combination and revision. symptomsEn: The system fails to boot with new modules, cannot reach the profile, or detects less memory than installed. diagnosisEn: Test modules individually in recommended slots at JEDEC defaults. Enable XMP/EXPO only after baseline testing. repairEn: Do not mix voltages and timings from incompatible profiles. A successful boot alone does not prove stability. warningEn: Record module models, part numbers and revisions.','',''),
('topic:TOPIC311-019','topic','','Diagnostyka wentylatorów i krzywej PWM/temperatura','Fan control and PWM/temperature curve diagnostics','description: Sprawdź typ 3-pin/4-pin, tachometer, PWM, sterowanie EC/BIOS, czujnik i profil. Nie każdy nagłówek lub kontroler obsługuje tę samą metodę. symptoms: Wentylator nie startuje, skacze z obrotami, hałasuje lub nie reaguje na zmianę obciążenia. diagnosis: Porównaj odczyt RPM z fizyczną pracą wentylatora. Zweryfikuj pinout i prąd znamionowy według instrukcji płyty. repair: Nie zatrzymuj wentylatora palcem ani narzędziem podczas pracy. Nie podłączaj pompy do nagłówka o nieznanym limicie prądowym. warning: Zapisz model wentylatora i nagłówka.','descriptionEn: Check 3-pin/4-pin type, tachometer, PWM, EC/BIOS control, sensor and profile. Not every header or controller supports the same method. symptomsEn: A fan fails to start, fluctuates, makes noise or does not respond to load changes. diagnosisEn: Compare RPM telemetry with physical fan operation. Verify pinout and rated current using the board manual. repairEn: Do not stop a running fan with a finger or tool. Do not connect a pump to a header with an unknown current limit. warningEn: Record fan and header model.','',''),
('topic:TOPIC311-020','topic','','Przygotowanie nośnika odzyskiwania i WinPE/WinRE','Recovery media and WinPE/WinRE preparation','description: Ustal tryb UEFI, architekturę, wersję Windows, sterownik storage/NVMe/RAID, Secure Boot i szyfrowanie. WinPE/WinRE musi pasować do platformy i zadania. symptoms: Komputer nie startuje, środowisko naprawcze nie widzi dysku lub brakuje sterownika kontrolera. diagnosis: Przygotuj nośnik na czystym USB, sprawdź sumę ISO/plików i zachowaj klucz BitLocker u właściciela. repair: Nie zapisuj klucza BitLocker w logu. Tworzenie nośnika może skasować USB — potwierdź wybrany dysk przed formatowaniem. warning: Zapisz edycję i architekturę Windows.','descriptionEn: Identify UEFI mode, Windows architecture/version, storage/NVMe/RAID driver, Secure Boot and encryption. WinPE/WinRE must match the platform and task. symptomsEn: The computer does not boot, recovery media cannot see the drive or a storage-controller driver is missing. diagnosisEn: Prepare media on a clean USB drive, verify ISO/file hashes and keep the BitLocker recovery key with the owner. repairEn: Do not record the BitLocker key in logs. Media creation can erase the USB drive—confirm the target before formatting. warningEn: Record Windows edition and architecture.','',''),
('topic:KURS320-001','topic','','Brak wykrywania dysku NVMe w UEFI','NVMe drive not detected in UEFI','description: Najpierw rozdziel zgodność formatu M.2 od protokołu SATA/NVMe, obsługę gniazda, współdzielenie linii PCIe, ustawienia UEFI i awarię samego nośnika. Sam wygląd M.2 nie gwarantuje zgodności. symptoms: Po instalacji dysku M.2 komputer nie widzi nośnika, instalator Windows nie pokazuje dysku albo wykrywanie jest niestabilne. diagnosis: Najpierw rozdziel zgodność formatu M.2 od protokołu SATA/NVMe, obsługę gniazda, współdzielenie linii PCIe, ustawienia UEFI i awarię samego nośnika. Sam wygląd M.2 nie gwarantuje zgodności. repair: Zweryfikuj numer modelu płyty/laptopa, generację i protokół gniazda. Testuj nośnik w zgodnym, znanym sprawnym komputerze; nie wykonuj inicjalizacji ani formatowania przed zabezpieczeniem danych.','descriptionEn: First separate M.2 form-factor compatibility from SATA/NVMe protocol, socket support, shared PCIe lanes, UEFI settings and drive failure. The M.2 shape alone does not guarantee compatibility. symptomsEn: After installing an M.2 drive, the firmware does not see it, Windows Setup cannot find it, or detection is intermittent. diagnosisEn: First separate M.2 form-factor compatibility from SATA/NVMe protocol, socket support, shared PCIe lanes, UEFI settings and drive failure. The M.2 shape alone does not guarantee compatibility. repairEn: Verify the exact system model, socket generation and supported protocol. Test the drive in a compatible known-good system; do not initialize or format it before protecting data. stepEn: Start with the following evidence-led repair path: Verify the exact system model, socket generation and supported protocol. Test the drive in a compatible known-good system; do not initialize or format it before protecting data. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-002','topic','','Interpretacja SMART i ostrzeżeń NVMe','SMART and NVMe warning interpretation','description: Nie sprowadzaj SMART do jednej procentowej wartości. Odczytaj właściwe atrybuty dla producenta i protokołu, log błędów, temperaturę, liczbę zapisów oraz krytyczne ostrzeżenia NVMe. symptoms: System zgłasza ostrzeżenie kondycji, rosnące błędy nośnika, niestabilny odczyt lub nagłe znikanie dysku. diagnosis: Nie sprowadzaj SMART do jednej procentowej wartości. Odczytaj właściwe atrybuty dla producenta i protokołu, log błędów, temperaturę, liczbę zapisów oraz krytyczne ostrzeżenia NVMe. repair: Jeżeli dane są ważne, najpierw utwórz obraz sektorowy lub kopię zgodnie z kondycją nośnika. Używaj narzędzia producenta i nie uruchamiaj długich benchmarków na dysku zagrożonym.','descriptionEn: Do not reduce SMART to a single health percentage. Read device-specific attributes, error logs, temperature, write volume and NVMe critical warnings. symptomsEn: The system reports a health warning, increasing media errors, unstable reads or sudden drive disappearance. diagnosisEn: Do not reduce SMART to a single health percentage. Read device-specific attributes, error logs, temperature, write volume and NVMe critical warnings. repairEn: If data matters, create a sector image or backup appropriate to the drive condition first. Use the manufacturer tool and avoid long benchmarks on a failing drive. stepEn: Start with the following evidence-led repair path: If data matters, create a sector image or backup appropriate to the drive condition first. Use the manufacturer tool and avoid long benchmarks on a failing drive. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-003','topic','','Ocena zużycia i temperatury SSD','SSD endurance and thermal assessment','description: Porównaj temperaturę kontrolera i NAND, throttling, procent zużycia, zapisane TB, zajętość oraz zachowanie po schłodzeniu. Dane SMART są zależne od producenta. symptoms: Dysk zwalnia przy długim transferze, przegrzewa się, osiąga wysokie opóźnienia albo zbliża się do limitu zapisów. diagnosis: Porównaj temperaturę kontrolera i NAND, throttling, procent zużycia, zapisane TB, zajętość oraz zachowanie po schłodzeniu. Dane SMART są zależne od producenta. repair: Zapewnij zgodny radiator i poprawny kontakt termiczny, sprawdź przepływ powietrza i firmware OEM. Przed zmianą firmware zabezpiecz dane i potwierdź dokładny model.','descriptionEn: Compare controller and NAND temperature, throttling, wear percentage, host writes, free space and behaviour after cooling. SMART fields vary by manufacturer. symptomsEn: The drive slows during sustained transfers, overheats, shows high latency or approaches its rated write endurance. diagnosisEn: Compare controller and NAND temperature, throttling, wear percentage, host writes, free space and behaviour after cooling. SMART fields vary by manufacturer. repairEn: Use a compatible heatsink and proper thermal contact, check airflow and OEM firmware. Protect data and verify the exact model before firmware changes. stepEn: Start with the following evidence-led repair path: Use a compatible heatsink and proper thermal contact, check airflow and OEM firmware. Protect data and verify the exact model before firmware changes. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-004','topic','','Diagnostyka dysku HDD z opóźnieniami i klikaniem','HDD delay and clicking diagnostics','description: Rozróżnij awarię mechaniczną, problemy z zasilaniem, kabel, elektronikę PCB i uszkodzenia powierzchni. Klikanie i powtarzające się próby rozruchu mogą wskazywać na poważną awarię mechaniczną. symptoms: Dysk twardy klika, długo inicjalizuje się, znika podczas kopiowania albo generuje błędy odczytu. diagnosis: Rozróżnij awarię mechaniczną, problemy z zasilaniem, kabel, elektronikę PCB i uszkodzenia powierzchni. Klikanie i powtarzające się próby rozruchu mogą wskazywać na poważną awarię mechaniczną. repair: Jeśli dane są ważne, wyłącz dysk i skieruj go do laboratorium odzyskiwania. Dla dysku stabilnego wykonaj kontrolowany obraz i dopiero kopię roboczą do analizy.','descriptionEn: Separate mechanical failure, power issues, cable faults, PCB electronics and media damage. Clicking and repeated spin-up attempts may indicate serious mechanical failure. symptomsEn: The hard drive clicks, takes a long time to initialize, disappears during copying or produces read errors. diagnosisEn: Separate mechanical failure, power issues, cable faults, PCB electronics and media damage. Clicking and repeated spin-up attempts may indicate serious mechanical failure. repairEn: If the data matters, power the drive down and refer it to a recovery lab. For a stable drive, create a controlled image and analyze a working copy. stepEn: Start with the following evidence-led repair path: If the data matters, power the drive down and refer it to a recovery lab. For a stable drive, create a controlled image and analyze a working copy. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-005','topic','','Odbudowa macierzy RAID po degradacji','RAID degraded-array recovery planning','description: Zidentyfikuj poziom RAID, kolejność dysków, kontroler, stan każdego nośnika i ostatnią poprawną kopię. Nie myl kolejności portów z kolejnością członków macierzy. symptoms: Macierz RAID zgłasza stan degraded, jeden dysk wypadł, wolumin działa tylko do odczytu albo odbudowa zatrzymuje się. diagnosis: Zidentyfikuj poziom RAID, kolejność dysków, kontroler, stan każdego nośnika i ostatnią poprawną kopię. Nie myl kolejności portów z kolejnością członków macierzy. repair: Zabezpiecz obrazy wszystkich nośników przed eksperymentami. Odbudowę uruchamiaj dopiero po potwierdzeniu, że pozostałe dyski są stabilne i istnieje plan odzyskiwania.','descriptionEn: Identify RAID level, member order, controller, each drive state and the last valid backup. Do not assume port order equals array-member order. symptomsEn: A RAID array reports degraded state, a drive has dropped out, the volume becomes read-only or rebuild stalls. diagnosisEn: Identify RAID level, member order, controller, each drive state and the last valid backup. Do not assume port order equals array-member order. repairEn: Image all member drives before experimentation. Start a rebuild only after confirming the remaining drives are stable and a recovery plan exists. stepEn: Start with the following evidence-led repair path: Image all member drives before experimentation. Start a rebuild only after confirming the remaining drives are stable and a recovery plan exists. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-006','topic','','USB-C: brak ładowania mimo sprawnego portu','USB-C no charging despite a working port','description: Sprawdź, czy port obsługuje ładowanie, jaka moc jest wymagana, czy źródło i kabel negocjują odpowiedni kontrakt PD oraz czy e-marker/kabel spełnia wymagania. symptoms: Urządzenie przesyła dane przez USB-C, ale nie ładuje się, ładuje wolno lub zmienia stan po poruszeniu przewodu. diagnosis: Sprawdź, czy port obsługuje ładowanie, jaka moc jest wymagana, czy źródło i kabel negocjują odpowiedni kontrakt PD oraz czy e-marker/kabel spełnia wymagania. repair: Testuj certyfikowany, odpowiednio znamionowany kabel i zasilacz; odczytaj kontrakt miernikiem zgodnym z USB-C/PD. Obejrzyj port przy odłączonym zasilaniu.','descriptionEn: Check whether the port supports charging, required power, whether source and cable negotiate the required PD contract and whether the cable/e-marker meets requirements. symptomsEn: The device transfers USB-C data but does not charge, charges slowly or changes state when the cable moves. diagnosisEn: Check whether the port supports charging, required power, whether source and cable negotiate the required PD contract and whether the cable/e-marker meets requirements. repairEn: Test with a certified, correctly rated cable and adapter; read the contract with a compliant USB-C/PD meter. Inspect the port with power disconnected. stepEn: Start with the following evidence-led repair path: Test with a certified, correctly rated cable and adapter; read the contract with a compliant USB-C/PD meter. Inspect the port with power disconnected. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-007','topic','','USB-C: dane działają, ale nie ma obrazu','USB-C data works but video is absent','description: Ustal obsługę DisplayPort Alt Mode, USB4 lub Thunderbolt w konkretnym porcie; sprawdź kabel, dock, firmware, liczbę monitorów, rozdzielczość i przepustowość. symptoms: Pendrive działa, ale monitor przez USB-C nie pokazuje obrazu lub działa tylko przy określonym kablu/docku. diagnosis: Ustal obsługę DisplayPort Alt Mode, USB4 lub Thunderbolt w konkretnym porcie; sprawdź kabel, dock, firmware, liczbę monitorów, rozdzielczość i przepustowość. repair: Zacznij od pojedynczego monitora i kabla o potwierdzonej specyfikacji. Testuj bez docka, potem dodawaj elementy pojedynczo.','descriptionEn: Verify DisplayPort Alt Mode, USB4 or Thunderbolt support on that exact port; check cable, dock, firmware, monitor count, resolution and bandwidth. symptomsEn: A USB drive works, but a monitor connected through USB-C has no image or works only with a specific cable or dock. diagnosisEn: Verify DisplayPort Alt Mode, USB4 or Thunderbolt support on that exact port; check cable, dock, firmware, monitor count, resolution and bandwidth. repairEn: Start with one monitor and a cable with confirmed specifications. Test without the dock, then add components one at a time. stepEn: Start with the following evidence-led repair path: Start with one monitor and a cable with confirmed specifications. Test without the dock, then add components one at a time. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-008','topic','','Niestabilna stacja dokująca Thunderbolt lub USB4','Unstable Thunderbolt or USB4 docking station','description: Rozdziel problemy z zasilaczem docka, kablem, firmware docka/hosta, zgodnością portu, topologią monitorów i sterownikami. symptoms: Monitory gasną, urządzenia USB znikają, dock resetuje się po wybudzeniu lub ogranicza prędkość transferu. diagnosis: Rozdziel problemy z zasilaczem docka, kablem, firmware docka/hosta, zgodnością portu, topologią monitorów i sterownikami. repair: Aktualizacje wykonuj wyłącznie dla dokładnego modelu docka i hosta. Przetestuj jeden monitor, jeden przewód i jeden peryferyjny element, zapisując wynik.','descriptionEn: Separate dock power supply, cable, dock/host firmware, port compatibility, monitor topology and driver faults. symptomsEn: Displays blank, USB devices disappear, the dock resets after wake or transfer speed is reduced. diagnosisEn: Separate dock power supply, cable, dock/host firmware, port compatibility, monitor topology and driver faults. repairEn: Update only for the exact dock and host models. Test one monitor, one cable and one peripheral at a time, recording the result. stepEn: Start with the following evidence-led repair path: Update only for the exact dock and host models. Test one monitor, one cable and one peripheral at a time, recording the result. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-009','topic','','Diagnostyka przeciążenia portu USB','USB port over-current diagnostics','description: Wyklucz uszkodzone akcesorium, kabel, zanieczyszczenia lub odkształcenie portu, uszkodzenie złącza wewnętrznego i układ zabezpieczenia. symptoms: System zgłasza przeciążenie portu, urządzenie odłącza się, port przestaje działać lub komputer wyłącza USB. diagnosis: Wyklucz uszkodzone akcesorium, kabel, zanieczyszczenia lub odkształcenie portu, uszkodzenie złącza wewnętrznego i układ zabezpieczenia. repair: Odłącz wszystkie urządzenia USB. Obejrzyj port bez zasilania, porównaj porty, a akcesoria podłączaj pojedynczo po wykluczeniu uszkodzeń.','descriptionEn: Exclude a faulty peripheral, cable, contamination or deformed port, internal header damage and protection-controller issues. symptomsEn: The system reports a port over-current condition, a device disconnects, the port stops working or USB power is disabled. diagnosisEn: Exclude a faulty peripheral, cable, contamination or deformed port, internal header damage and protection-controller issues. repairEn: Disconnect every USB device. Inspect the port with power removed, compare ports and reconnect peripherals individually after ruling out damage. stepEn: Start with the following evidence-led repair path: Disconnect every USB device. Inspect the port with power removed, compare ports and reconnect peripherals individually after ruling out damage. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-010','topic','','Trening pamięci DDR5 i długi pierwszy start','DDR5 memory training and long first boot','description: Sprawdź moduły, sloty zalecane przez instrukcję, wersję BIOS, zgodność QVL i ustawienia JEDEC/XMP/EXPO. Czas treningu zależy od platformy i konfiguracji. symptoms: Po zmianie RAM komputer długo nie wyświetla obrazu, kilkukrotnie restartuje się lub kończy na diodzie DRAM. diagnosis: Sprawdź moduły, sloty zalecane przez instrukcję, wersję BIOS, zgodność QVL i ustawienia JEDEC/XMP/EXPO. Czas treningu zależy od platformy i konfiguracji. repair: Przywróć parametry bazowe i pozwól platformie ukończyć trening zgodnie z instrukcją płyty. Testuj pojedyncze moduły i zalecane kombinacje.','descriptionEn: Check modules, recommended slots, BIOS version, QVL compatibility and JEDEC/XMP/EXPO settings. Training time depends on platform and configuration. symptomsEn: After a RAM change, the PC shows no image for a long time, restarts repeatedly or stops at the DRAM LED. diagnosisEn: Check modules, recommended slots, BIOS version, QVL compatibility and JEDEC/XMP/EXPO settings. Training time depends on platform and configuration. repairEn: Restore baseline settings and allow the platform to complete training according to the board manual. Test single modules and recommended combinations. stepEn: Start with the following evidence-led repair path: Restore baseline settings and allow the platform to complete training according to the board manual. Test single modules and recommended combinations. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-011','topic','','Błędy RAM: moduł, slot czy kontroler pamięci','RAM errors: module, slot or memory controller','description: Testuj moduły osobno, w slotach wskazanych przez instrukcję. Sprawdź ustawienia JEDEC, temperaturę, docisk chłodzenia CPU i możliwy problem IMC. symptoms: Test pamięci wykrywa błędy, występują BSOD, aplikacje zamykają się lub system nie przechodzi POST. diagnosis: Testuj moduły osobno, w slotach wskazanych przez instrukcję. Sprawdź ustawienia JEDEC, temperaturę, docisk chłodzenia CPU i możliwy problem IMC. repair: Przywróć ustawienia bazowe, przetestuj znany sprawny moduł i udokumentuj kombinację moduł/slot oraz wzór błędów.','descriptionEn: Test modules individually in slots specified by the manual. Check JEDEC settings, temperature, CPU cooler pressure and possible IMC issues. symptomsEn: A memory test reports errors, BSODs occur, applications close or the system fails POST. diagnosisEn: Test modules individually in slots specified by the manual. Check JEDEC settings, temperature, CPU cooler pressure and possible IMC issues. repairEn: Restore baseline settings, test a known-good module and document module/slot combinations and the error pattern. stepEn: Start with the following evidence-led repair path: Restore baseline settings, test a known-good module and document module/slot combinations and the error pattern. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-012','topic','','GPU: artefakty obrazu i błędy VRAM','GPU artifacts and VRAM error diagnostics','description: Porównaj monitor, kabel, port, zrzut ekranu i wyjście zintegrowane. Zapisz temperaturę core/hotspot/VRAM, taktowania, sterownik i log TDR. symptoms: Pojawiają się kolorowe piksele, pasy, migotanie, błędy tekstur lub awarie pod obciążeniem. diagnosis: Porównaj monitor, kabel, port, zrzut ekranu i wyjście zintegrowane. Zapisz temperaturę core/hotspot/VRAM, taktowania, sterownik i log TDR. repair: Przywróć ustawienia fabryczne GPU, zmień tylko jeden element toru obrazu i wykonaj krótki kontrolowany test.','descriptionEn: Compare monitor, cable, port, screenshot and integrated output. Record core/hotspot/VRAM temperature, clocks, driver and TDR logs. symptomsEn: Coloured pixels, bands, flicker, texture errors or crashes under load appear. diagnosisEn: Compare monitor, cable, port, screenshot and integrated output. Record core/hotspot/VRAM temperature, clocks, driver and TDR logs. repairEn: Restore GPU defaults, change one display-path component at a time and run a short controlled test. stepEn: Start with the following evidence-led repair path: Restore GPU defaults, change one display-path component at a time and run a short controlled test. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-013','topic','','TDR i reset sterownika karty graficznej','GPU driver TDR and reset diagnostics','description: Sprawdź zdarzenia, wersję sterownika, aktualizację Windows, temperaturę i stabilność zasilania. Oddziel problem aplikacji od sprzętu. symptoms: Ekran miga, sterownik odzyskuje działanie, aplikacja 3D zamyka się lub pojawia się kod błędu sterownika. diagnosis: Sprawdź zdarzenia, wersję sterownika, aktualizację Windows, temperaturę i stabilność zasilania. Oddziel problem aplikacji od sprzętu. repair: Utwórz punkt przywracania, użyj sterownika OEM lub dostawcy GPU i wykonaj kontrolowany rollback/clean install zgodnie z dokumentacją.','descriptionEn: Check event logs, driver version, Windows update history, temperature and power stability. Separate application issues from hardware faults. symptomsEn: The screen flickers, the driver recovers, a 3D application closes or a graphics-driver error appears. diagnosisEn: Check event logs, driver version, Windows update history, temperature and power stability. Separate application issues from hardware faults. repairEn: Create a restore point, use OEM or GPU-vendor drivers and perform a controlled rollback/clean install according to documentation. stepEn: Start with the following evidence-led repair path: Create a restore point, use OEM or GPU-vendor drivers and perform a controlled rollback/clean install according to documentation. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-014','topic','','EDID, rozdzielczość i migotanie monitora','EDID, display mode and monitor flicker','description: Porównaj EDID, wejście monitora, kabel, przejściówkę, port GPU i tryby obrazu obsługiwane przez wszystkie elementy łańcucha. symptoms: Monitor jest wykrywany jako ogólny, brakuje natywnej rozdzielczości, odświeżanie jest ograniczone lub obraz zanika. diagnosis: Porównaj EDID, wejście monitora, kabel, przejściówkę, port GPU i tryby obrazu obsługiwane przez wszystkie elementy łańcucha. repair: Testuj bez przejściówek, z innym zgodnym kablem i pojedynczym ekranem. Instaluj sterownik monitora tylko ze sprawdzonego źródła.','descriptionEn: Compare EDID, monitor input, cable, adapter, GPU port and display modes supported by every component in the chain. symptomsEn: The monitor is detected as generic, native resolution is missing, refresh is limited or the image drops out. diagnosisEn: Compare EDID, monitor input, cable, adapter, GPU port and display modes supported by every component in the chain. repairEn: Test without adapters, using another compatible cable and a single display. Install monitor drivers only from a verified source. stepEn: Start with the following evidence-led repair path: Test without adapters, using another compatible cable and a single display. Install monitor drivers only from a verified source. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-015','topic','','Matryca eDP: brak podświetlenia przy widocznym obrazie','eDP display: image present but no backlight','description: Odróżnij usterkę podświetlenia, taśmy eDP, złącza, czujnika pokrywy, panelu i zasilania podświetlenia. Nie zakładaj pinoutu z innej matrycy. symptoms: Pod latarką widać bardzo słaby obraz, ale ekran jest ciemny; monitor zewnętrzny działa. diagnosis: Odróżnij usterkę podświetlenia, taśmy eDP, złącza, czujnika pokrywy, panelu i zasilania podświetlenia. Nie zakładaj pinoutu z innej matrycy. repair: Oceń taśmę i złącze przy odłączonej baterii. Pomiary wykonuj tylko według schematu właściwej płyty i panelu.','descriptionEn: Separate backlight, eDP cable, connector, lid sensor, panel and backlight-power faults. Never assume pinout from another panel. symptomsEn: A faint image is visible under a flashlight but the panel is dark; an external monitor works. diagnosisEn: Separate backlight, eDP cable, connector, lid sensor, panel and backlight-power faults. Never assume pinout from another panel. repairEn: Inspect cable and connector with the battery disconnected. Measure only according to the correct board and panel schematics. stepEn: Start with the following evidence-led repair path: Inspect cable and connector with the battery disconnected. Measure only according to the correct board and panel schematics. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-016','topic','','Wentylator: sygnał PWM i brak odczytu RPM','Fan PWM control and missing RPM feedback','description: Sprawdź zgodność pinów, napięcie zasilania, sygnał sterujący PWM, tachometr, przewód i sterowanie EC. Nie podłączaj wentylatora tylko na podstawie kształtu wtyczki. symptoms: Wentylator nie startuje, działa stale na maksymalnych obrotach albo BIOS pokazuje 0 RPM. diagnosis: Sprawdź zgodność pinów, napięcie zasilania, sygnał sterujący PWM, tachometr, przewód i sterowanie EC. Nie podłączaj wentylatora tylko na podstawie kształtu wtyczki. repair: Porównaj z właściwą częścią OEM. Testuj na bezpiecznym stanowisku i monitoruj temperaturę; naprawa przewodu lub złącza wymaga identyfikacji pinów.','descriptionEn: Check pin compatibility, supply voltage, PWM control, tachometer, cable and EC control. Do not connect a fan by connector shape alone. symptomsEn: The fan does not start, runs constantly at maximum speed or BIOS reports 0 RPM. diagnosisEn: Check pin compatibility, supply voltage, PWM control, tachometer, cable and EC control. Do not connect a fan by connector shape alone. repairEn: Compare with the correct OEM part. Test safely while monitoring temperature; cable or connector repair requires confirmed pin identification. stepEn: Start with the following evidence-led repair path: Compare with the correct OEM part. Test safely while monitoring temperature; cable or connector repair requires confirmed pin identification. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-017','topic','','Chłodzenie CPU: docisk i nierównomierne temperatury','CPU cooling contact and uneven temperatures','description: Sprawdź montaż, folię ochronną, kolejność dokręcania, pastę, nierówność podstawy, pompę/AIO, obroty i przepływ powietrza. symptoms: CPU szybko osiąga limit termiczny, jeden rdzeń jest nietypowo gorący lub taktowanie spada po krótkim obciążeniu. diagnosis: Sprawdź montaż, folię ochronną, kolejność dokręcania, pastę, nierówność podstawy, pompę/AIO, obroty i przepływ powietrza. repair: Zdemontuj chłodzenie zgodnie z instrukcją, oczyść odpowiednim środkiem i zastosuj właściwy materiał termiczny. Dokręcaj równomiernie.','descriptionEn: Check mounting, protective film, tightening sequence, thermal paste, base flatness, pump/AIO, fan speed and airflow. symptomsEn: The CPU quickly reaches a thermal limit, one core is unusually hot or clocks drop after brief load. diagnosisEn: Check mounting, protective film, tightening sequence, thermal paste, base flatness, pump/AIO, fan speed and airflow. repairEn: Remove the cooler according to instructions, clean with a suitable product and apply the correct thermal interface. Tighten evenly. stepEn: Start with the following evidence-led repair path: Remove the cooler according to instructions, clean with a suitable product and apply the correct thermal interface. Tighten evenly. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-018','topic','','Uszkodzenia po zalaniu: ocena przed pierwszym startem','Liquid damage assessment before first power-on','description: Zidentyfikuj rodzaj cieczy, obszar i czas zdarzenia. Oceń korozję pod osłonami i złączami; brak widocznych śladów nie wyklucza pozostałości. symptoms: Urządzenie wyłączyło się po kontakcie z cieczą, występuje korozja, lepki osad albo niestabilne zasilanie. diagnosis: Zidentyfikuj rodzaj cieczy, obszar i czas zdarzenia. Oceń korozję pod osłonami i złączami; brak widocznych śladów nie wyklucza pozostałości. repair: Nie uruchamiaj urządzenia. Odłącz zasilacz i baterię zgodnie z procedurą, dokumentuj obszar i oceń potrzebę profesjonalnego czyszczenia/naprawy płyty.','descriptionEn: Identify liquid type, affected area and exposure time. Inspect corrosion under shields and connectors; absence of visible damage does not rule out residue. symptomsEn: The device shut down after liquid exposure, corrosion, sticky residue or unstable power is present. diagnosisEn: Identify liquid type, affected area and exposure time. Inspect corrosion under shields and connectors; absence of visible damage does not rule out residue. repairEn: Do not power the device on. Disconnect adapter and battery according to procedure, document the area and assess need for professional cleaning/board repair. stepEn: Start with the following evidence-led repair path: Do not power the device on. Disconnect adapter and battery according to procedure, document the area and assess need for professional cleaning/board repair. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-019','topic','','Klawiatura laptopa: diagnostyka matrycy klawiszy','Laptop keyboard matrix diagnostics','description: Oddziel problem układu klawiszy, taśmy, złącza ZIF, zalania, kontrolera EC i ustawień języka/układu. symptoms: Nie działają całe rzędy klawiszy, klawiatura wpisuje znaki losowo lub przestaje działać po poruszeniu obudowy. diagnosis: Oddziel problem układu klawiszy, taśmy, złącza ZIF, zalania, kontrolera EC i ustawień języka/układu. repair: Sprawdź układ systemowy i klawiaturę zewnętrzną. Po odłączeniu zasilania obejrzyj taśmę i zatrzask; wymieniaj tylko część zgodną z FRU/PN.','descriptionEn: Separate keyboard matrix, ribbon, ZIF connector, liquid damage, EC controller and language/layout settings. symptomsEn: Entire key rows fail, random characters appear or the keyboard stops after case movement. diagnosisEn: Separate keyboard matrix, ribbon, ZIF connector, liquid damage, EC controller and language/layout settings. repairEn: Check the OS layout and an external keyboard. With power removed, inspect the ribbon and latch; replace only a matching FRU/part. stepEn: Start with the following evidence-led repair path: Check the OS layout and an external keyboard. With power removed, inspect the ribbon and latch; replace only a matching FRU/part. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-020','topic','','Touchpad: awaria I2C, HID lub sterownika','Touchpad I2C, HID and driver diagnostics','description: Porównaj BIOS/UEFI, Menedżer urządzeń, I2C/HID, zdarzenia sterownika, taśmę i ustawienia Fn. Sprawdź, czy problem dotyczy urządzenia czy sterownika. symptoms: Touchpad znika z Menedżera urządzeń, działa po starcie i przestaje po uśpieniu albo gesty nie działają. diagnosis: Porównaj BIOS/UEFI, Menedżer urządzeń, I2C/HID, zdarzenia sterownika, taśmę i ustawienia Fn. Sprawdź, czy problem dotyczy urządzenia czy sterownika. repair: Testuj w systemie OEM i po czystym rozruchu. Aktualizuj sterownik z portalu producenta, a złącze sprawdzaj po odłączeniu baterii.','descriptionEn: Compare BIOS/UEFI, Device Manager, I2C/HID, driver events, cable and Fn settings. Determine whether the fault is hardware or driver-related. symptomsEn: The touchpad disappears from Device Manager, works after boot but fails after sleep, or gestures stop working. diagnosisEn: Compare BIOS/UEFI, Device Manager, I2C/HID, driver events, cable and Fn settings. Determine whether the fault is hardware or driver-related. repairEn: Test with the OEM image and a clean boot. Update drivers from the manufacturer portal; inspect the connector with the battery disconnected. stepEn: Start with the following evidence-led repair path: Test with the OEM image and a clean boot. Update drivers from the manufacturer portal; inspect the connector with the battery disconnected. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-021','topic','','Kamera: urządzenie USB, prywatność i blokada sprzętowa','Camera USB, privacy and hardware switch diagnostics','description: Sprawdź fizyczną przesłonę, przełącznik Fn, politykę prywatności, uprawnienia, Menedżer urządzeń, taśmę i magistralę USB. symptoms: Kamera nie pojawia się w systemie, jest czarny obraz lub aplikacja nie ma uprawnień. diagnosis: Sprawdź fizyczną przesłonę, przełącznik Fn, politykę prywatności, uprawnienia, Menedżer urządzeń, taśmę i magistralę USB. repair: Najpierw sprawdź ustawienia i aplikację referencyjną. Jeśli sprzęt znika również poza systemem, sprawdź złącze i przewód zgodnie z dokumentacją.','descriptionEn: Check physical shutter, Fn switch, privacy policy, permissions, Device Manager, cable and USB bus. symptomsEn: The camera is missing, shows a black image or the application lacks permissions. diagnosisEn: Check physical shutter, Fn switch, privacy policy, permissions, Device Manager, cable and USB bus. repairEn: Check settings and a reference application first. If hardware is missing outside the OS too, inspect the connector and cable according to documentation. stepEn: Start with the following evidence-led repair path: Check settings and a reference application first. If hardware is missing outside the OS too, inspect the connector and cable according to documentation. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-022','topic','','Ethernet: negocjacja prędkości i błędy linku','Ethernet link negotiation and error diagnostics','description: Sprawdź port switcha/routera, kabel i kategorię, długość, autotuning, sterownik NIC, ustawienia duplex i błędy licznika. symptoms: Link negocjuje 100 Mb/s zamiast 1/2.5/10 Gb/s, gubi pakiety albo rozłącza się przy obciążeniu. diagnosis: Sprawdź port switcha/routera, kabel i kategorię, długość, autotuning, sterownik NIC, ustawienia duplex i błędy licznika. repair: Porównaj dwa znane sprawne kable i porty. Nie wymuszaj full duplex ani prędkości bez potwierdzenia możliwości obu końców.','descriptionEn: Check switch/router port, cable category, length, autonegotiation, NIC driver, duplex settings and error counters. symptomsEn: The link negotiates 100 Mb/s instead of 1/2.5/10 Gb/s, loses packets or disconnects under load. diagnosisEn: Check switch/router port, cable category, length, autonegotiation, NIC driver, duplex settings and error counters. repairEn: Compare two known-good cables and ports. Do not force duplex or speed without confirming both ends support it. stepEn: Start with the following evidence-led repair path: Compare two known-good cables and ports. Do not force duplex or speed without confirming both ends support it. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-023','topic','','Wi-Fi: różnicowanie sterownika, anten i routera','Wi-Fi driver, antenna and router fault isolation','description: Porównaj inne urządzenie w tej samej lokalizacji, pasmo, kanał, roaming, sterownik, anteny, przewody i zakłócenia. symptoms: Sygnał jest słaby, połączenie zrywa się po zamknięciu pokrywy lub prędkość różni się między pasmami. diagnosis: Porównaj inne urządzenie w tej samej lokalizacji, pasmo, kanał, roaming, sterownik, anteny, przewody i zakłócenia. repair: Przetestuj blisko routera, następnie w miejscu problemu. Anteny i przewody sprawdzaj przy odłączonej baterii; użyj dokumentacji modelu.','descriptionEn: Compare another device in the same location, band, channel, roaming, driver, antennas, cables and interference. symptomsEn: Signal is weak, connection drops when the lid closes or speed differs between bands. diagnosisEn: Compare another device in the same location, band, channel, roaming, driver, antennas, cables and interference. repairEn: Test near the router and then at the problem location. Inspect antennas and cables with the battery disconnected, using model documentation. stepEn: Start with the following evidence-led repair path: Test near the router and then at the problem location. Inspect antennas and cables with the battery disconnected, using model documentation. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-024','topic','','Bluetooth: parowanie, sterownik i zakłócenia','Bluetooth pairing, driver and interference diagnostics','description: Rozdziel błędy parowania, pamięci urządzeń, usług systemowych, sterownika, anteny combo i zakłócenia 2.4 GHz. symptoms: Urządzenia nie parują się, rozłączają lub dźwięk przerywa mimo prawidłowego działania Wi-Fi. diagnosis: Rozdziel błędy parowania, pamięci urządzeń, usług systemowych, sterownika, anteny combo i zakłócenia 2.4 GHz. repair: Usuń stare parowanie, testuj jedno urządzenie referencyjne, sprawdź sterownik WLAN/BT i aktualizacje OEM.','descriptionEn: Separate pairing cache, device memory, system services, driver, combo antenna and 2.4 GHz interference. symptomsEn: Devices fail to pair, disconnect or audio stutters while Wi-Fi works. diagnosisEn: Separate pairing cache, device memory, system services, driver, combo antenna and 2.4 GHz interference. repairEn: Remove old pairings, test one reference device and check WLAN/BT drivers and OEM updates. stepEn: Start with the following evidence-led repair path: Remove old pairings, test one reference device and check WLAN/BT drivers and OEM updates. Record the baseline condition and repeat the original test after any change.','',''),
('topic:KURS320-025','topic','','Audio: codec, sterownik i gniazdo jack','Audio codec, driver and jack diagnostics','description: Sprawdź wyjście domyślne, mikser, usługi, sterownik OEM, kodek, gniazdo i czujnik jack. Porównaj USB/Bluetooth i analog. symptoms: Brak dźwięku, szum, brak wykrywania słuchawek lub urządzenie audio znika po aktualizacji. diagnosis: Sprawdź wyjście domyślne, mikser, usługi, sterownik OEM, kodek, gniazdo i czujnik jack. Porównaj USB/Bluetooth i analog. repair: Zacznij od testu na słuchawkach i innym wyjściu. Cofnij tylko sterownik, który koreluje z objawem; obejrzyj gniazdo bez zasilania.','descriptionEn: Check default output, mixer, services, OEM driver, codec, jack and jack-detect. Compare USB/Bluetooth and analog. symptomsEn: No sound, noise, headphones are not detected or the audio device disappears after an update. diagnosisEn: Check default output, mixer, services, OEM driver, codec, jack and jack-detect. Compare USB/Bluetooth and analog. repairEn: Start with headphones and another output. Roll back only a driver that correlates with the symptom; inspect the jack with power removed. stepEn: Start with the following evidence-led repair path: Start with headphones and another output. Roll back only a driver that correlates with the symptom; inspect the jack with power removed. Record the baseline condition and repeat the original test after any change.','','');
